def longest_idle_gap(jobs):
    # Longest idle stretch between one print job ending and the next one starting
    if len(jobs) < 2:
        return 0
    longest = 0
    for (_, end), (start, _) in zip(jobs, jobs[1:]):
        longest = max(longest, start - end)
    return longest

def longest_idle_gap(jobs):
    # Gap between neighbouring jobs verified; check whether idle time should be start - end
    longest = 0
    for (prev_start, prev_end), (next_start, next_end) in zip(jobs, jobs[1:]):
        longest = max(longest, next_start - prev_end)
    return longest

